import decimal
import math
import re
import logging


class ExcelFormulaTranslator:
    """
    Class for calculating xlsx formulas at interpreting time .
    """
    def __init__(self):
        pass
        log_format = "%(levelname)s %(asctime)s - %(message)s"
        logging.basicConfig(level=logging.DEBUG, filemode='w', format=log_format)

    @staticmethod
    def __sum(*argv):
        """
        Excel SUM() function equivalent

        :param *argv: variadic number of arguments

        :return: Calculated sum from passed arguments
        """
        sum_value = 0
        for arg in argv:
            sum_value += arg
        return sum_value

    @staticmethod
    def __average(*argv):
        """
        Excel AVERAGE() function equivalent

        :param *argv: variadic number of arguments

        :return: Calculated average from passed arguments
        """
        sum_value = 0
        for arg in argv:
            sum_value += arg
        return sum_value / len(argv)

    @staticmethod
    def __max(*argv):
        """
        Excel MAX() function equivalent

        :param *argv: variadic number of arguments

        :return: Max value from passed arguments
        """
        max_value = argv[0]
        for arg in argv:
            if arg > max_value:
                max_value = arg
        return max_value

    @staticmethod
    def __min(*argv):
        """
        Excel MIN() function equivalent

        :param *argv: variadic number of arguments

        :return: Min value from passed arguments
        """
        min_value = argv[0]
        for arg in argv:
            if arg < min_value:
                min_value = arg
        return min_value

    @staticmethod
    def __error_value_to_savable_format(error_value):
        error_value = error_value.replace('\"', '')
        if error_value.replace('.', '').isdigit():
            error_value = float(error_value)
        return error_value

    def calculate_formula(self, formula):
        """
        Evaluates passed Excel formula

        :param formula: Excel formula

        :return: Evaluated excel formula
        """

        if re.findall(r'^=IFERROR', formula):
            last_comma = formula.rfind(",")
            error_value = formula[last_comma + 1:-1]
            formula = formula[9:last_comma].lower()

        else:
            error_value = 'NA'
        formula = formula.lower()
        try:
            result = decimal.Decimal(eval(formula,
                                          {'log': math.log, 'power': math.pow},
                                          {'sum': self.__sum, 'avg': self.__average,
                                           'max': self.__max, 'min': self.__min})).quantize(decimal.Decimal('0.00'))
            return result
        except NameError as nam_err:
            if "na" not in str(nam_err):
                logging.warning("Unrecognised phrase in formula, {} "
                                "may be a new, not supported function "
                                "used by EXCEL formula, "
                                "contacting developers is advised".format(nam_err))

        return self.__error_value_to_savable_format(error_value)
